sql.where:
s.status = '在读'

AND c.grade = #{grade}
AND s.class_id = #{classId}

  AND (s.name LIKE CONCAT('%', #{keyword}, '%') OR s.sid LIKE CONCAT('%', #{keyword}, '%'))

AND COALESCE(day.status, '出勤') <> '出勤'

mapper.select:
SELECT COALESCE(SUM(COALESCE(day.status, '出勤') = '出勤'), 0) AS present,
       COALESCE(SUM(COALESCE(day.status, '出勤') = '迟到'), 0) AS late,
       COALESCE(SUM(COALESCE(day.status, '出勤') = '缺勤'), 0) AS absent,
       COALESCE(SUM(COALESCE(day.status, '出勤') = '请假'), 0) AS `leave`
FROM student s
JOIN class_info c ON c.class_id = s.class_id
LEFT JOIN attendance_record day ON day.student_id = s.id AND day.attend_date = #{date}

  s.status = '在读'

  AND c.grade = #{grade}
  AND s.class_id = #{classId}

SELECT id, student_id, attend_date, status, remark
FROM attendance_record
WHERE student_id = #{studentId}
ORDER BY attend_date DESC
LIMIT #{size}
